+class TestStableChunkBuild(SimpleTestCase):
+    """The stable chunk build is an LCP experiment against the current build.
+
+    Logged-in users are enrolled by the stable-chunk-build flag (the flag's rollout
+    percentage is the split). The stable-chunks query param still forces the build and
+    does not enroll. Logged-out visitors are never enrolled.
+    """
+
+    def _request(self, path: str = "/", *, authenticated: bool = False, email: str = "person@posthog.com"):
+        request = RequestFactory().get(path)
+        if authenticated:
+            request.user = cast(
+                Any,
+                type(
+                    "User",
+                    (),
+                    {
+                        "is_authenticated": True,
+                        "email": email,
+                        "distinct_id": "user-distinct",
+                        "date_joined": datetime(2024, 6, 1, tzinfo=ZoneInfo("UTC")),
+                        "organization": None,
+                    },
+                )(),
+            )
+        else:
+            request.user = AnonymousUser()
+        return request
+
+    def test_logged_out_visitor_is_not_enrolled_and_stays_on_the_current_build(self):
+        request = self._request()
+        with patch("posthog.utils.posthoganalytics.feature_enabled") as mock_flag:
+            assert _stable_chunk_build_enabled(request, None) is False
+        mock_flag.assert_not_called()
+
+    def test_query_param_forces_the_stable_build_without_enrolling(self):
+        request = self._request("/?stable-chunks=1")
+        with patch("posthog.utils.posthoganalytics.feature_enabled") as mock_flag:
+            assert _stable_chunk_build_enabled(request, None) is True
+        mock_flag.assert_not_called()
+
+    def test_logged_in_query_param_forces_the_build_and_skips_the_flag(self):
+        request = self._request("/?stable-chunks", authenticated=True)
+        with patch("posthog.utils.posthoganalytics.feature_enabled", return_value=False) as mock_flag:
+            assert _stable_chunk_build_enabled(request, "user-distinct") is True
+        mock_flag.assert_not_called()
+
+    @parameterized.expand([("off", False), ("on", True)])
+    def test_logged_in_user_is_enrolled_and_served_by_the_flag(self, _name: str, flag_value: bool):
+        request = self._request(authenticated=True)
+        with patch("posthog.utils.posthoganalytics.feature_enabled", return_value=flag_value) as mock_flag:
+            assert _stable_chunk_build_enabled(request, "user-distinct") is flag_value
+        assert mock_flag.call_args.args[0] == STABLE_CHUNK_BUILD_FLAG
+        assert mock_flag.call_args.args[1] == "user-distinct"
+        assert mock_flag.call_args.kwargs["only_evaluate_locally"] is True
+        assert mock_flag.call_args.kwargs["person_properties"]["email"] == "person@posthog.com"
+        # Default is to send $feature_flag_called. Passing False would bucket nobody into the experiment.
+        assert mock_flag.call_args.kwargs.get("send_feature_flag_events", True) is True
+
+    def test_explicit_off_query_does_not_force_the_build(self):
+        request = self._request("/?stable-chunks=0", authenticated=True)
+        with patch("posthog.utils.posthoganalytics.feature_enabled", return_value=False) as mock_flag:
+            assert _stable_chunk_build_enabled(request, "user-distinct") is False
+        mock_flag.assert_called_once()
+
+    def test_a_failed_flag_lookup_serves_the_current_build(self):
+        request = self._request(authenticated=True)
+        with patch("posthog.utils.posthoganalytics.feature_enabled", side_effect=Exception("flags down")):
+            assert _stable_chunk_build_enabled(request, "user-distinct") is False
+
+    @patch("posthog.utils._resolve_entry_assets", return_value=("static/a.css", ("static/a.js",), "static/font.woff2"))
+    def test_current_build_emits_no_preload_hints(self, mock_assets):
+        request = self._request(authenticated=True)
+        with patch("posthog.utils.posthoganalytics.feature_enabled", return_value=False):
+            assert _index_shell_assets(request, "user-distinct") == (False, "", (), "")
+        mock_assets.assert_not_called()
+
+    @patch("posthog.utils._resolve_entry_assets", return_value=("static/a.css", ("static/a.js",), "static/font.woff2"))
+    def test_stable_build_preloads_the_boot_chain(self, mock_assets):
+        request = self._request("/?stable-chunks=1", authenticated=True)
+        assert _index_shell_assets(request, "user-distinct") == (
+            True,
+            "static/a.css",
+            ("static/a.js",),
+            "static/font.woff2",
+        )
+        mock_assets.assert_called_once_with(True)
+
