+# Boolean flag. Its rollout percentage is the split: at 50%, half of logged-in users
+# are served the stable chunk build and half stay on the current build. Local evaluation
+# sends $feature_flag_called, which is the exposure the LCP comparison needs.
+STABLE_CHUNK_BUILD_FLAG = "stable-chunk-build"
+# Manual opt-in. Forces the stable build for that document and does not enroll anyone —
+# logged-out visitors included.
+STABLE_CHUNK_BUILD_QUERY_PARAM = "stable-chunks"
+_STABLE_CHUNK_BUILD_OFF_VALUES = frozenset({"0", "false", "no"})
+
+
+def _query_forces_stable_chunk_build(request: HttpRequest) -> bool:
+    params = getattr(request, "GET", None)
+    if not isinstance(params, Mapping):
+        return False
+    if STABLE_CHUNK_BUILD_QUERY_PARAM not in params:
+        return False
+    value = (params.get(STABLE_CHUNK_BUILD_QUERY_PARAM) or "").strip().lower()
+    return value not in _STABLE_CHUNK_BUILD_OFF_VALUES
+
+
+def _stable_chunk_build_enabled(request: HttpRequest, distinct_id: Optional[str]) -> bool:
+    """Whether this document should load the stable chunk build.
+
+    The stable build is the parallel chunk map plus the boot preload hints. It improves
+    LCP and, until the flag below, only reached a browser via the ``stable-chunks`` query
+    param. Logged-out visitors are never enrolled: the flag is not evaluated for them, so
+    they stay on the current build unless they pass that param. Logged-in users are
+    bucketed by ``stable-chunk-build`` (local evaluation only, so the HTML response does
+    not wait on a flags network call). The param still forces the stable build and skips
+    evaluation, so a manual opt-in does not enroll that page view.
+    """
+    if _query_forces_stable_chunk_build(request):
+        return True
+    user = getattr(request, "user", None)
+    if not distinct_id or user is None or not getattr(user, "is_authenticated", False):
+        return False
+
+    person_properties: dict[str, Any] = {}
+    email = getattr(user, "email", None)
+    if email:
+        person_properties["email"] = email
+    date_joined = getattr(user, "date_joined", None)
+    if date_joined is not None:
+        person_properties["joined_at"] = date_joined.isoformat()
+
+    groups: dict[str, str] = {}
+    group_properties: dict[str, dict[str, Any]] = {}
+    organization = getattr(user, "organization", None)
+    if organization is not None:
+        groups["organization"] = str(organization.id)
+        created_at = getattr(organization, "created_at", None)
+        group_properties["organization"] = {
+            "name": getattr(organization, "name", None),
+            "created_at": created_at.isoformat() if created_at is not None else None,
+        }
+
+    try:
+        # Local evaluation holds conditions but not stored person properties, so pass the
+        # same properties the bootstrap flags call uses. A failed lookup serves the current
+        # build rather than guessing a variant.
+        return (
+            posthoganalytics.feature_enabled(
+                STABLE_CHUNK_BUILD_FLAG,
+                distinct_id,
+                groups=groups or None,
+                person_properties=person_properties,
+                group_properties=group_properties or None,
+                only_evaluate_locally=True,
+            )
+            is True
+        )
+    except Exception:
+        logger.warning("stable_chunk_build.flag_check_failed", exc_info=True)
+        return False
+
+
